package com.hbm.client.generator.stirling;
import com.hbm.hazard.HbmHazards;import com.hbm.machine.generator.stirling.*;import mezz.jei.api.*;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.ingredients.subtypes.*;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class StirlingJeiPlugin implements IModPlugin {
 private static final RecipeType<StirlingViews.View> TYPE=RecipeType.create("hbm","stirling",StirlingViews.View.class);@Override public ResourceLocation getPluginUid(){return ResourceLocation.parse("hbm:stirling_jei");}@Override public void registerCategories(IRecipeCategoryRegistration event){event.addRecipeCategories(new Category(event.getJeiHelpers().getGuiHelper()));}@Override public void registerRecipes(IRecipeRegistration event){event.addRecipes(TYPE,StirlingViews.views());}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration event){for(var item:StirlingContent.ITEM.values())event.addRecipeCatalysts(TYPE,item.get());}@Override public void registerExtraIngredients(IExtraIngredientRegistration event){event.addExtraIngredients(VanillaTypes.ITEM_STACK,StirlingContent.allStacks());}@Override public void registerItemSubtypes(ISubtypeRegistration event){for(var item:StirlingContent.ITEM.values())event.registerSubtypeInterpreter(item.get(),new ISubtypeInterpreter<ItemStack>(){@Override public Object getSubtypeData(ItemStack stack,UidContext context){return stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),0);}@Override public String getLegacyStringSubtypeInfo(ItemStack stack,UidContext context){return getSubtypeData(stack,context).toString();}});}
 private static final class Category implements IRecipeCategory<StirlingViews.View>{private final IDrawable background,icon;Category(IGuiHelper helper){background=helper.createBlankDrawable(166,65);icon=helper.createDrawableItemStack(new ItemStack(StirlingContent.ITEM.get(StirlingKind.NORMAL).get()));}@Override public RecipeType<StirlingViews.View> getRecipeType(){return TYPE;}@Override public Component getTitle(){return Component.translatable("block.hbm.machine_stirling");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder builder,StirlingViews.View recipe,IFocusGroup focus){builder.addSlot(RecipeIngredientRole.CATALYST,74,24).addItemStack(recipe.machine());}@Override public void draw(StirlingViews.View recipe,IRecipeSlotsView slots,GuiGraphics g,double x,double y){StirlingViews.draw(g,recipe,0,0);}}
}
